INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('b0babc48-830b-51fe-add6-ab7a50678ca2', '2c524bae-c97a-54a8-8b66-a201ab5bd999', 'en', $h$What is a klingerite gasket used for?$h$, $h$<div> <p>Klingerite gaskets are formed from a mixture of graphite and fiber, and provide reliable sealing at flange, valve and pipe connections.</p> </div>$h$) ON CONFLICT DO NOTHING;
