INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('d32c4923-fbe2-51fc-ade0-ff941c6e7101', 'f986861f-9f9f-5337-80a7-cf8ca2f722de', 'en', $h$What is the difference between a graphite gasket and a standard gasket?$h$, $h$<div> <p>Graphite gaskets provide high temperature and chemical resistance; standard gaskets are for lower-performance environments.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('76065fc3-ae66-5c40-a7db-a9b5755db22e', '95a3a6fc-96f1-52ed-b228-95262bfd989d', 'en', $h$Teflon and Self-Adhesive Teflon Gasket$h$, $h$teflon-and-self-adhesive-teflon-gasket$h$, $h$Teflon & Self-Adhesive Teflon Gaskets – High-Performance Sealing Elements$h$, $h$<div> <p><strong>Teflon gaskets (PTFE gaskets)</strong> and <strong>self-adhesive Teflon gaskets</strong> are high-performance sealing elements used to provide <strong>high chemical resistance, low friction and excellent sealing</strong> at industrial pipelines, valve connections, pump bodies and various mechanical assembly points.</p><p>Since PTFE material is resistant to chemicals, high temperatures and abrasive environments, these gaskets are preferred particularly in <strong>applications involving aggressive fluids</strong>. Self-adhesive Teflon gaskets additionally offer <strong>easy positioning</strong> during application and a <strong>fast installation advantage</strong>.</p> </div><div> <p>✔ <strong>High chemical resistance:</strong> Resistant to acids, alkalis and aggressive fluids<br/>✔ <strong>Wide temperature tolerance:</strong> Safe use from -200°C up to +260°C<br/>✔ <strong>Low friction:</strong> Minimized during installation and use<br/>✔ <strong>Easy installation (self-adhesive):</strong> Practical application with a self-adhesive surface<br/>✔ <strong>Long service life:</strong> High-performance and durable PTFE material</p> </div>$h$, $h$<div> <p>HD Marine Teflon and Self-Adhesive Teflon gaskets provide effective sealing in the following applications:</p><ul><li>Industrial pipe and flange connections</li><li>Chemical and petrochemical plants</li><li>Abrasive chemical transfer lines</li><li>Shipboard marine systems</li><li>Processes requiring high temperature/chemical resistance</li></ul><p>These gaskets provide reliable and long-lasting sealing, particularly in <strong>circuits where chemicals are conveyed</strong>.</p> </div>$h$, $h$Teflon and Self-Adhesive Teflon Gasket | HD Marine$h$, $h$Teflon gaskets (PTFE gaskets) and self-adhesive Teflon gaskets are high-performance sealing elements used to provide high chemical resistance, low…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('91b6711c-6cee-59b7-b8f8-b6b4402a04e3', '4cba1f47-1f16-54f0-a800-5aa0c5cdead2', 'en', $h$What is a Teflon gasket?$h$, $h$<div> <p>A Teflon gasket is a sealing element made from PTFE material, providing high chemical resistance and low friction.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('5bb65626-3a69-5f1b-8831-5dd027da8494', '71c69d49-eab4-5103-bd53-b1e4bee9b7f2', 'en', $h$What is a self-adhesive Teflon gasket used for?$h$, $h$<div> <p>The self-adhesive Teflon gasket is designed for easy positioning on slippery surfaces during installation and fast setup.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('703ea36f-7566-5667-a05f-509122ee10d7', '3f60d539-a57c-5cb1-a8a3-ff6e98263644', 'en', $h$In which applications is it preferred?$h$, $h$<div> <p>It is preferred in chemical plants, pipe flanges, valve connections, pump bodies and aggressive fluid circuits.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('cbf53722-a024-533c-821e-6aecd25b0fb4', 'fce488e2-077e-5a85-9743-bbc2e9b0bdd3', 'en', $h$What is the temperature resistance of a Teflon gasket?$h$, $h$<div> <p>Teflon gaskets are durable across a wide temperature range from -200°C to +260°C.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('0d1e975a-5cfd-5dbb-80e2-3f8f293d0b1f', 'a201e609-01d4-588c-b4b8-2ebafa6f8669', 'en', $h$Soft Packings$h$, $h$soft-packings$h$, $h$Soft Packings – High Sealing Performance and Durability$h$, $h$<div> <p><strong>Soft packings</strong> are elastic sealing elements that provide <strong>sealing and mechanical isolation</strong> by closing the gap between the shaft and the housing. They are widely used in pipeline systems, pumps, valves, rotor shaft connections and industrial mechanisms to prevent leaks of water, oil, fuel and various fluids.</p><p>HD Marine soft packings deliver long-lasting performance with their <strong>flexible structure, high chemical compatibility and durable material</strong>.</p> </div><div> <p>✔ <strong>Superior sealing:</strong> Effectively prevents liquid and gas leaks<br/>✔ <strong>Flexible and conformable:</strong> Full seating on the shaft surface and stretching capability<br/>✔ <strong>Chemical resistance:</strong> Resistance to water, oil, fuel and mild chemicals<br/>✔ <strong>Low friction:</strong> Minimizes wear<br/>✔ <strong>Easy installation:</strong> Practical and fast setup</p> </div>$h$, $h$<div> <p>HD Marine soft packings provide <strong>sealing and long-life performance</strong> particularly in:</p><ul><li>Industrial <strong>pump and valve shafts</strong></li><li><strong>Pipelines</strong> and process circuits</li><li>Marine and shipping applications</li><li>Engine rooms and mechanical systems</li><li>Pressurized system connections</li></ul><p>and similar operations.</p> </div>$h$, $h$Soft Packings | HD Marine$h$, $h$Soft packings are elastic sealing elements that provide sealing and mechanical isolation by closing the gap between the shaft and the housing. They are…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('da872a7f-44f1-59f7-b046-21172acee9c4', 'fc718e63-4041-52c4-8c70-5120dc3b07df', 'en', $h$What is a soft packing?$h$, $h$<div> <p>A soft packing is a flexible sealing element that prevents liquid or gas leaks by closing the gaps between the shaft and the hub.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('f41cfeeb-f4a3-5178-8e1d-f0ddf89ee473', '7ff03678-077f-539e-a9d6-70f6ab81c46d', 'en', $h$From which materials is it made?$h$, $h$<div> <p>It is generally produced from NBR, Viton, neoprene or elastomer compounds; the choice depends on the application.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('c2ac6913-9d5a-5f6a-af09-652e64347bae', 'e8f6d425-13b9-5820-af77-80dbfb90de1c', 'en', $h$Where is it used?$h$, $h$<div> <p>It is used on pump shafts, valves, rotor connections and process piping.</p> </div>$h$) ON CONFLICT DO NOTHING;
