INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('bd568d9c-0754-5b9c-9ee2-3527d56a4c20', '15d6e92a-fc27-58f7-9f04-75b237090ebd', 'en', $h$Hatch Cover Tapes$h$, $h$hatch-cover-tapes$h$, $h$Hatch Cover Tapes – Marine and Industrial Sealing Solution$h$, $h$<div> <p><strong>Hatch cover tapes</strong> are special tapes designed to <strong>provide sealing and insulation for hatch covers</strong> on ships, marine vessels and industrial facilities. They are resistant to vibration, water or oil contact occurring during operation, and by forming an effective barrier at cover joints they <strong>prevent water ingress, smoke passage and corrosion.</strong></p><p>HD Marine hatch cover tapes provide reliable sealing in both the marine and industrial sectors with their long-lasting flexible structure and high resistance.</p> </div><div> <p>✔ <strong>High sealing performance:</strong> Effective barrier against water, oil, dust and contamination<br/>✔ <strong>Flexible and durable material:</strong> Adapts to vibration and temperature changes<br/>✔ <strong>Easy application:</strong> Fast installation in tape form<br/>✔ <strong>Resistance to UV and weather conditions:</strong> Long life in marine and outdoor environments<br/>✔ <strong>Wide range of use:</strong> Hatch covers, valve covers, door/frame sealing</p> </div>$h$, $h$<div> <p><strong>Hatch cover tapes provide high resistance and reliable sealing, particularly in:</strong></p><ul><li>Hatch cover sealing on ships</li><li>Cover and frame insulation on marine vessels</li><li>Industrial cover, valve and panel connections</li><li>Applications preventing water and oil passage</li><li>Sealing on vibrating surfaces</li></ul><p>and similar applications.</p> </div>$h$, $h$Hatch Cover Tapes | HD Marine$h$, $h$Hatch cover tapes are special tapes designed to provide sealing and insulation for hatch covers on ships, marine vessels and industrial facilities. They…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('55bde08f-5663-5501-9de1-6c3cffc7b8b3', '2f58a222-e5ce-5b6b-adba-33441227e82e', 'en', $h$What is a hatch cover tape?$h$, $h$<div> <p>A hatch cover tape is a sealing material that prevents the ingress of water, air and contamination at cover and frame joints.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('018079a3-a085-57e2-9e78-27143b360241', '99a81e44-d386-5a12-9cc2-1876ecbca7a0', 'en', $h$With which materials is it compatible?$h$, $h$<div> <p>It has an elastomeric structure compatible with most metals, plastics, composites and marine surfaces.</p> </div>$h$) ON CONFLICT DO NOTHING;
