INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('84207006-31b0-56b1-ab44-cf540fbe519d', 'fd82ac1d-3c38-5447-8efc-b43f460caf61', 'en', $h$Pipe Repair Clamps$h$, $h$pipe-repair-clamps$h$, $h$Pipe Repair Clamps – Fast and Reliable Pipe Repair Solution$h$, $h$<div> <p><strong>Pipe repair clamps</strong> are connection elements used to <strong>repair damage such as leaks, cracks or holes in pipes quickly, practically and safely</strong>. They save time and money by returning piping systems to service across different application areas, from industrial facilities to marine lines.</p><p>HD Marine pipe repair clamps, with their durable construction, quality materials and easy installation advantage, provide an effective solution for <strong>water, oil, fuel and other fluid lines</strong>.</p> </div><div> <p>✔ <strong>Fast installation:</strong> Simply tighten the bolts<br/>✔ <strong>Suitable for various pipe diameters:</strong> From 15 mm up to 500 mm<br/>✔ <strong>Durable gasket:</strong> Broad fluid compatibility with EPDM / NBR options<br/>✔ <strong>High pressure resistance:</strong> Suitable for industrial lines<br/>✔ <strong>Corrosion resistance:</strong> Galvanized or stainless options</p> </div>$h$, $h$<div> <ul><li>Industrial process piping</li><li>Marine machinery and line systems</li><li>Water and wastewater facilities</li><li>Fuel and oil transfer lines</li><li>Chemical pipelines</li></ul><p>Pipe repair clamps provide a fast and economical solution for stopping a pipeline failure or making a temporary repair.</p> </div>$h$, $h$Pipe Repair Clamps | HD Marine$h$, $h$Pipe repair clamps are connection elements used to repair damage such as leaks, cracks or holes in pipes quickly, practically and safely . They save time…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('52933371-ebd7-5ed8-be3f-0e007f47ab20', '0f148a81-d430-5d53-8c44-d557865730ec', 'en', $h$What is a pipe repair clamp?$h$, $h$<div> <p>A pipe repair clamp is a connection element used to close leaks, cracks and holes in pipelines quickly and practically.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('d9012be7-2664-556a-9de1-fc65d178d585', '061a0eef-c760-512e-b93e-2cb2e525c6af', 'en', $h$For which pipe diameters is it used?$h$, $h$<div> <p>It can be used on pipelines of various diameters from 25 mm up to 300 mm.</p> </div>$h$) ON CONFLICT DO NOTHING;
