INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('91ec7d3a-8e03-5dd3-bd7a-8434626a3695', '96481a3c-8428-5c0f-b4e5-eff02323331e', 'en', $h$Is installation difficult?$h$, $h$<div> <p>No. Thanks to the bolted system, it provides fast and easy installation.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('154c7e07-9d3c-5dd2-ac53-28b052248938', 'ad803e91-7fdc-522a-8463-09137fb264f2', 'en', $h$Pipe Repair Bandage$h$, $h$pipe-repair-bandage$h$, $h$Pipe Repair Bandage – A Practical and Permanent Repair Solution$h$, $h$<div> <p>A <strong>pipe repair bandage</strong> is an <strong>after-production repair bandage</strong> used to quickly repair damage such as cracks, tears or abrasions in pipelines. Thanks to its elastic and durable structure, it enables pipes that will not close, are leaking or have been damaged to return to service in a short time.</p><p>HD Marine pipe repair bandages offer an effective repair solution in marine, industrial and infrastructure applications with their <strong>high strength</strong>, <strong>corrosion resistance</strong> and <strong>long service life</strong>.</p> </div><div> <p>✔ <strong>Fast application:</strong> Applied practically by wrapping<br/>✔ <strong>Durable material:</strong> High strength with fiberglass + epoxy<br/>✔ <strong>Suitable for various pipe diameters:</strong> Use from 25 to 250 mm<br/>✔ <strong>High pressure resistance:</strong> Suitable for industrial facilities<br/>✔ <strong>Corrosion resistance:</strong> Resistant to fluids such as water, oil and chemicals</p> </div><div> <p><strong>🛠️ Where Is It Used?</strong></p><p>HD Marine pipe repair bandages provide reliable and fast solutions for <strong>leak and damage repair</strong> particularly in:</p><ul><li>Water and wastewater lines</li><li>Fuel and oil transfer pipes</li><li>Industrial process lines</li><li>Marine and engine room applications</li><li>Chemical line repairs</li></ul><p>and other different sectors.</p> </div>$h$, NULL, $h$Pipe Repair Bandage | HD Marine$h$, $h$A pipe repair bandage is an after-production repair bandage used to quickly repair damage such as cracks, tears or abrasions in pipelines. Thanks to its…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('05d4c8c5-3a0e-568f-bf0b-98a370465195', '97ce1a11-a4d7-51d1-96a0-2770fa02fa3d', 'en', $h$What is a pipe repair bandage?$h$, $h$<div> <p>A pipe repair bandage is a reinforcement bandage used to repair cracked or damaged pipelines in a practical and durable way.</p> </div>$h$) ON CONFLICT DO NOTHING;
