INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('9e44cbce-fcc0-5333-8dfd-ec564818b9c2', '92bc84e5-81ec-5e8e-a036-a9084c8551d4', 'en', $h$How is it applied?$h$, $h$<div> <p>After the damaged area is cleaned, the bandage is wrapped and pressure is applied over it; it hardens in a short time.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('29fe96a3-73ce-5896-8d66-1cfc4c181ca7', '46f27085-ba12-5e21-a5e0-97fcc6ec11fb', 'en', $h$On which pipe types can it be used?$h$, $h$<div> <p>It can be used safely on water, oil, fuel and most industrial fluid lines.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('af536285-338c-56d7-bb68-fed1b9d63960', '97d52c9e-efec-5786-8e65-ed989fa790f0', 'en', $h$Marine Chemicals$h$, $h$marine-chemicals$h$, $h$Marine Chemicals – Professional Solutions for Shipping and Marine Applications$h$, $h$<div> <p>The HD Marine marine chemicals category includes <strong>chemical products specially formulated for ship maintenance, cleaning, protection and improving operational performance in the maritime sector</strong>. These products cover a wide range of uses, from ship surface maintenance to fuel and oil systems, from ship cleaning to environmental protection applications.</p><p>Delivering high performance under demanding conditions at sea, marine chemicals provide reliable solutions for both commercial vessels and yacht/boat owners.</p> </div><div> <p>HD Marine marine chemicals are used for the following purposes:</p><ul><li>🛥️ <strong>Ship surface cleaning and polishing</strong></li><li>🛠️ <strong>Engine, fuel and oil system maintenance</strong></li><li>🛡️ <strong>Corrosion-inhibiting and rust-dissolving applications</strong></li><li>♻️ <strong>Wastewater treatment and environmental protection support products</strong></li><li>⛽ <strong>Fuel additives and performance enhancers</strong></li></ul><p>These products are formulated to suit the characteristics of the marine environment and offer <strong>high effectiveness with low environmental impact</strong>.</p> </div><div> <p>✔ Optimized for maritime conditions<br/>✔ Highly effective formulation<br/>✔ Non-abrasive, safe use<br/>✔ Environmentally friendly alternatives available<br/>✔ Compliant with industrial and marine standards</p> </div><div> <ul><li><strong>Ship surface cleaners</strong> – Salt water, oil and dirt removers</li><li><strong>Engine and machinery maintenance chemicals</strong> – Protective oils, rust removers</li><li><strong>Fuel additives</strong> – Performance and fuel efficiency enhancers</li><li><strong>Antifreeze and water removers</strong> – Freezing, moisture and corrosion prevention</li><li><strong>Wastewater and environmental products</strong> – Treatment chemicals compliant with environmental standards</li></ul><p>Each product category delivers professional results aimed at optimizing ship maintenance processes and increasing operational efficiency.</p> </div>$h$, NULL, $h$Marine Chemicals | HD Marine$h$, $h$The HD Marine marine chemicals category includes chemical products specially formulated for ship maintenance, cleaning, protection and improving…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('f8756013-b676-583f-b8b0-1c3cfb44e4e5', 'af4337f1-6553-5905-94d2-5beb2265ead5', 'en', $h$What are marine chemicals used for?$h$, $h$<div> <p>Marine chemicals are specially formulated products for cleaning, maintenance, surface protection and improving system performance in the marine environment.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('028b3b52-8b28-501e-94fe-412e4fef4909', '8c3471c7-bf39-5601-95f3-455d1900b287', 'en', $h$Which marine chemicals are available?$h$, $h$<div> <p>Various categories are available, such as surface cleaners, engine maintenance products, fuel additives, rust dissolvers and environmental products.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('8e210d48-6919-5531-a6aa-aa6c79312d13', 'ae2bccbe-28ac-5252-af69-63ca483e6ef6', 'en', $h$Is it safe to use in a marine environment?$h$, $h$<div> <p>HD Marine products are formulated for safe use in compliance with maritime standards.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('5d1e7bc3-5f54-5ef3-9289-94747f03a264', '43f9eedf-b3fb-5af2-867b-a9becee5cb1a', 'en', $h$Are the chemicals environmentally friendly?$h$, $h$<div> <p>Many products have environmentally friendly formulations compliant with environmental standards.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('c049a024-5054-5e36-9d32-c35ebe623b4a', '0a28d2bd-c819-5452-a7f5-8f39aee0b28b', 'en', $h$Thermal Label$h$, $h$thermal-label$h$, $h$Temperature Indicator Labels – Instant and Permanent Heat Monitoring Solutions$h$, $h$<div> <p><strong>Temperature indicator labels</strong> are practical and reliable measurement solutions that provide temperature monitoring by changing color or leaving a permanent mark when a specific temperature level is reached. They operate without requiring electronic sensors and offer fast checks particularly on <strong>industrial equipment, pipelines, motors, electrical panels and in shipping processes</strong>.</p><p>HD Marine temperature indicator labels are an effective solution for <strong>overheating detection</strong>, <strong>process control</strong>, <strong>maintenance planning</strong> and <strong>transport safety</strong>.</p> </div><div> <p>These labels:</p><ul><li>Activate within a predetermined temperature range</li><li>Provide a visual warning by changing color</li><li>Can be single-use (irreversible) or multi-level</li><li>Require no external power source</li></ul><p>They are used as an early warning mechanism, particularly in systems at risk of overheating.</p> </div>$h$, $h$<div> <p>Temperature indicator labels are used for <strong>instant heat monitoring and overheating detection</strong> particularly in areas such as:</p><ul><li>Electrical panels</li><li>Motor and gearbox systems</li><li>Steam lines</li><li>Industrial machinery</li><li>Transport and logistics (temperature-controlled products)</li><li>Marine engine rooms</li></ul> </div><div> <p>✔ Requires no electronic sensors<br/>✔ Easy application (stick and use)<br/>✔ Low-cost temperature monitoring<br/>✔ Visual and fast inspection capability<br/>✔ Provides early warning in maintenance processes</p> </div>$h$, $h$Thermal Label | HD Marine$h$, $h$Temperature indicator labels are practical and reliable measurement solutions that provide temperature monitoring by changing color or leaving a permanent…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('3670aa70-0217-5aff-b19c-84e48768fdae', 'dcbd8da3-4c06-58d2-8c6b-b3a7ccc0bdae', 'en', $h$How does a temperature indicator label work?$h$, $h$<div> <p>When the defined temperature level is reached, it changes color through a chemical reaction and leaves a permanent mark.</p> </div>$h$) ON CONFLICT DO NOTHING;
