INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('2a72e0a8-8456-5bde-8cfc-95927588fbed', '2dfaa1a6-6b7d-5d57-8095-c3ae02046018', 'en', $h$In which temperature range does it operate?$h$, $h$<div> <p>Depending on the model, different threshold options are available from 30°C up to 260°C.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('85f4f7de-a0f3-5880-82a7-3e46c9111425', '1de0cabb-27b9-535f-9f93-44acfa779898', 'en', $h$Industrial Chemicals$h$, $h$industrial-chemicals$h$, NULL, $h$<div> <p>Metal surface treatment chemicals play a critical role in the <strong>cleaning, preparation, protection and coating</strong> processes of metal surfaces in industrial applications. The high-performance chemical solutions we offer at HD Marine increase production efficiency while raising surface quality to the maximum level.</p><p>Our broad product portfolio has been specially developed for <strong>oil, dirt and oxide removal</strong>, surface activation, corrosion protection and pre-coating preparation processes. It can be used safely on different surface types, including iron and steel, stainless steel, aluminum and alloyed metals.</p> </div><div> <p>Cleaning chemicals used in preparing metal surfaces before coating or assembly ensure the effective removal of all unwanted residues from the surface.</p> </div><div> <ul><li>Industrial oil and grease removers</li><li>Alkaline and acidic cleaners</li><li>Rust and oxide removers</li><li>Pre-phosphate surface preparation chemicals</li><li>Solvent-based and water-based cleaners</li></ul> </div><div> <ul><li>High cleaning performance</li><li>Effective results without damaging the surface</li><li>Excellent surface preparation before coating</li><li>Time and cost savings in work processes</li></ul> </div><div> <p>Coating chemicals protect metal surfaces against external factors while also imparting aesthetic and functional properties.</p> </div><div> <ul><li>Phosphating chemicals (zinc, iron, manganese)</li><li>Passivation and protective coating products</li><li>Corrosion-inhibiting chemicals</li><li>Pre-paint surface preparation chemicals</li><li>Temporary protective film and coating solutions</li></ul> </div><div> <ul><li>Long-term corrosion resistance</li><li>Improved coating and paint adhesion performance</li><li>Durability under demanding industrial conditions</li><li>Achieving a homogeneous, high-quality surface</li></ul> </div><div> <ul><li>Shipping and ship maintenance-repair</li><li>Iron-steel and metalworking industry</li><li>Automotive and supplier industry</li><li>Chemical and process industries</li><li>Energy and heavy industry facilities</li></ul> </div><div> <ul><li>Products meeting high quality standards</li><li>Formulation options tailored to different processes</li><li>Fast supply and competitive price advantage</li><li>Technical consultancy and field support</li></ul> </div>$h$, NULL, $h$Industrial Chemicals | HD Marine$h$, $h$Metal surface treatment chemicals play a critical role in the cleaning, preparation, protection and coating processes of metal surfaces in industrial…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('7b4cf80d-f58b-581e-b0b3-e32c236af0e1', '64f700b2-09bd-5e50-8ae0-e0b6fffb5c51', 'en', $h$Sine Lobe Pump$h$, $h$sine-lobe-pump$h$, $h$Lobe Pump – High-Efficiency Positive Displacement Transfer$h$, $h$<div> <p>A <strong>lobe pump (rotary lobe pump)</strong> is a type of positive displacement pump consisting of lobed rotors. Thanks to this design, it provides <strong>low shear, high efficiency and precise flow control</strong>. Sine lobe pumps are the ideal solution for handling <strong>viscous liquids, particle-laden fluids and delicate products</strong> without problems.</p><p>HD Marine sine lobe pumps, with their durable body construction and superior performance, deliver <strong>uninterrupted liquid transfer</strong> in industrial facilities, marine applications and production lines.</p> </div><div> <ul><li>🌟 <strong>High performance:</strong> Constant flow rate and low energy consumption</li><li>⚙ <strong>Product safety:</strong> Low shear preserves product structure</li><li>🧰 <strong>Easy maintenance:</strong> Fast cleaning and maintenance after use</li><li>🏭 <strong>Broad application compatibility:</strong> Food, chemicals, marine and industry</li></ul> </div>$h$, $h$<div> <p>HD Marine lobe pumps are preferred particularly in the following sectors:</p><ul><li><strong>Food and beverage production</strong> (e.g. syrups, sauces)</li><li><strong>Chemical and pharmaceutical processes</strong></li><li><strong>Wastewater and filtration systems</strong></li><li><strong>Paint, ink and solvent transfer lines</strong></li><li><strong>Marine and industrial applications</strong></li></ul><p>The breadth of application areas makes sine lobe pumps highly versatile.</p> </div>$h$, $h$Sine Lobe Pump | HD Marine$h$, $h$A lobe pump (rotary lobe pump) is a type of positive displacement pump consisting of lobed rotors. Thanks to this design, it provides low shear, high…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('d5fdda09-48f3-56c6-9f97-3914607ff227', '63022ab7-668d-5da7-9d44-9fc07d1d7a9d', 'en', $h$What is a lobe pump?$h$, $h$<div> <p>It is a type of pump operating with positive displacement lobed rotors, providing liquid transfer at a constant flow rate.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('88473e90-6138-58de-b67d-62aecf3a12d3', '915a0f68-53e5-534f-acf8-682e663f496c', 'en', $h$With what kinds of liquids is it used?$h$, $h$<div> <p>It is used with fluids requiring delicate transfer, such as viscous liquids, particle-laden fluids, food products and chemicals.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('c652adca-faa7-56e0-9240-2e6fd99725c6', '5edefd86-e423-5dec-a45b-b8443cd0ee1e', 'en', $h$What is the advantage of a lobe pump?$h$, $h$<div> <p>With low shear, it minimizes product degradation and provides constant flow.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('5e5e14df-af3a-51b4-a4d4-6eea292727d8', '8cb1f7a2-a4a9-581b-828b-f17489b304c9', 'en', $h$Who should choose it?$h$, $h$<div> <p>Food, pharmaceutical and chemical production plants, and all industrial applications requiring delicate fluid transfer.</p> </div>$h$) ON CONFLICT DO NOTHING;
